import{_ as r,o as t,c as a,a5 as l}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"10045-框选自动裁切图片选定文件夹自动加载整个文件夹图片按钮切换下一张图片","日期":"2026-04-10T00:00:00.000Z","修改日期":"2026-04-10T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["图像框选工具","图像编辑工具","图像裁剪工具","批量处理图像","批量裁剪","比例裁剪","照片裁剪软件"]},"headers":[],"relativePath":"md/图片批处理/10045-框选自动裁切图片选定文件夹自动加载整个文件夹图片按钮切换下一张图片.md","filePath":"md/图片批处理/10045-框选自动裁切图片选定文件夹自动加载整个文件夹图片按钮切换下一张图片.md"}'),i={name:"md/图片批处理/10045-框选自动裁切图片选定文件夹自动加载整个文件夹图片按钮切换下一张图片.md"};function n(s,o,e,p,g,h){return t(),a("div",null,[...o[0]||(o[0]=[l('<h3 id="_10045-框选自动裁切图片选定文件夹自动加载整个文件夹图片按钮切换下一张图片" tabindex="-1">10045-框选自动裁切图片选定文件夹自动加载整个文件夹图片按钮切换下一张图片 <a class="header-anchor" href="#_10045-框选自动裁切图片选定文件夹自动加载整个文件夹图片按钮切换下一张图片" aria-label="Permalink to &quot;10045-框选自动裁切图片选定文件夹自动加载整个文件夹图片按钮切换下一张图片&quot;">​</a></h3><p>本程序用于快速裁剪图片，支持自由裁剪和固定比例裁剪（如1:1、4:3、16:9等）。程序会读取选择的文件夹中的所有图片文件，并允许逐一裁剪图片。 裁剪后的图片将按照原图片文件名保存在原文件夹中的一个名为“cropped_images”的文件夹内。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251021165217176103673725127.png" alt=""></p><h3 id="主要亮点" tabindex="-1"><strong>主要亮点：</strong> <a class="header-anchor" href="#主要亮点" aria-label="Permalink to &quot;**主要亮点：**&quot;">​</a></h3><ul><li>支持多种预设裁剪比例和自由裁剪模式</li><li>批量处理文件夹中的所有图像</li><li>简单直观的鼠标框选操作</li><li>自动保存裁剪结果到指定文件夹</li><li>完整的图像导航功能</li></ul><p><strong>适用人群：</strong> 摄影师、设计师、内容创作者、需要批量处理图像的办公人员</p><h3 id="功能速览" tabindex="-1">功能速览 <a class="header-anchor" href="#功能速览" aria-label="Permalink to &quot;功能速览&quot;">​</a></h3><p>📁 <strong>文件夹批量处理</strong> - 一次性选择多个图像进行处理</p><p>📏 <strong>多种裁剪比例</strong> - 内置11种常用裁剪比例和自由裁剪</p><p>🖱️ <strong>鼠标框选操作</strong> - 简单直观的可视化裁剪</p><p>📊 <strong>自动比例调整</strong> - 根据选择的比例自动优化裁剪区域</p><p>➡️ <strong>图像导航</strong> - 轻松浏览文件夹中的所有图像</p><p>💾 <strong>自动保存</strong> - 裁剪结果自动保存到指定目录</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250115223430173695167060903.png" alt=""></p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>比如选择了一个包含多张图片的文件夹，程序会自动加载该文件夹中的图片，可以通过鼠标框选的方式裁剪图片，并选择裁剪的比例。 裁剪后的图片会自动保存到“cropped_images”文件夹中，文件名与原图片保持一致。</p><h3 id="界面导览" tabindex="-1">界面导览 <a class="header-anchor" href="#界面导览" aria-label="Permalink to &quot;界面导览&quot;">​</a></h3><p><strong>主界面各区域功能：</strong></p><ul><li><strong>图像显示区域</strong> - 顶部大型区域，显示当前待裁剪的图像</li><li><strong>功能按钮区域</strong> - 包含选择文件夹、裁剪比例选择、裁剪按钮</li><li><strong>导航按钮区域</strong> - 包含上一张和下一张按钮</li><li><strong>信息显示区域</strong> - 显示当前图片名称</li><li><strong>日志记录区域</strong> - 底部显示最近的操作记录</li></ul><p><strong>核心操作按钮介绍：</strong></p><ul><li><strong>点击选择文件夹</strong> - 选择包含需要裁剪图像的文件夹</li><li><strong>裁剪比例选项</strong> - 选择预设裁剪比例或自由裁剪模式</li><li><strong>裁剪图像按钮</strong> - 点击后进入裁剪模式，然后用鼠标框选裁剪区域</li><li><strong>上一张/下一张</strong> - 在文件夹中的图像间导航</li></ul><p><strong>日志区域使用提示：</strong></p><ul><li>包含裁剪图像的保存路径</li></ul><h3 id="功能详解" tabindex="-1">功能详解 <a class="header-anchor" href="#功能详解" aria-label="Permalink to &quot;功能详解&quot;">​</a></h3><h4 id="文件夹选择功能" tabindex="-1">文件夹选择功能 <a class="header-anchor" href="#文件夹选择功能" aria-label="Permalink to &quot;文件夹选择功能&quot;">​</a></h4><p><strong>功能用途：</strong> 选择包含待处理图像的文件夹</p><p><strong>操作步骤：</strong></p><ol><li>点击「点击选择文件夹」按钮</li><li>在弹出的对话框中选择包含图像的文件夹</li><li>程序会自动加载文件夹中的所有图像（支持jpg、jpeg、png、bmp格式）</li><li>自动创建「cropped_images」子文件夹用于保存裁剪结果</li></ol><h4 id="裁剪比例选择功能" tabindex="-1">裁剪比例选择功能 <a class="header-anchor" href="#裁剪比例选择功能" aria-label="Permalink to &quot;裁剪比例选择功能&quot;">​</a></h4><p><strong>功能用途：</strong> 设置图像的裁剪比例</p><p><strong>参数说明：</strong></p><ul><li>自由裁剪：不限制比例，完全按照鼠标框选区域裁剪</li><li>预设比例：提供11种常用比例（1:1, 4:3, 16:9, 3:2, 2:3, 5:4, 4:5, 8:10, 10:8, 3:6, 9:16）</li></ul><p><strong>操作步骤：</strong></p><ol><li>从下拉菜单中选择所需的裁剪比例</li><li>选择后自动进入裁剪模式</li></ol><h4 id="图像裁剪功能" tabindex="-1">图像裁剪功能 <a class="header-anchor" href="#图像裁剪功能" aria-label="Permalink to &quot;图像裁剪功能&quot;">​</a></h4><p><strong>功能用途：</strong> 裁剪图像并保存结果</p><p><strong>操作步骤：</strong></p><ol><li>选择裁剪比例</li><li>点击「裁剪图像」按钮</li><li>在图像上按住鼠标左键拖拽，框选需要保留的区域</li><li>释放鼠标后，程序自动裁剪并保存图像</li></ol><p><strong>自动比例调整：</strong> 当选择了固定比例时，程序会根据框选区域自动调整为精确的比例，确保最终裁剪结果符合选择的比例要求。</p><h4 id="图像导航功能" tabindex="-1">图像导航功能 <a class="header-anchor" href="#图像导航功能" aria-label="Permalink to &quot;图像导航功能&quot;">​</a></h4><p><strong>功能用途：</strong> 在文件夹中的多个图像间切换</p><p><strong>操作步骤：</strong></p><ul><li>点击「上一张图片」查看上一个图像</li><li>点击「下一张」查看下一个图像</li></ul><h3 id="实用场景示例" tabindex="-1">实用场景示例 <a class="header-anchor" href="#实用场景示例" aria-label="Permalink to &quot;实用场景示例&quot;">​</a></h3><h4 id="场景一-社交媒体图片裁剪" tabindex="-1">场景一：社交媒体图片裁剪 <a class="header-anchor" href="#场景一-社交媒体图片裁剪" aria-label="Permalink to &quot;场景一：社交媒体图片裁剪&quot;">​</a></h4><p><strong>场景描述：</strong> 需要将一组照片裁剪成正方形（1:1）用于社交媒体发布</p><p><strong>前置条件：</strong></p><ul><li>准备好所有需要处理的照片，放在同一个文件夹中</li><li>安装好程序及依赖</li></ul><p><strong>操作步骤：</strong></p><ol><li>启动程序</li><li>点击「点击选择文件夹」选择照片所在文件夹</li><li>从下拉菜单中选择「1:1」比例</li><li>点击「裁剪图像」按钮</li><li>在图像上框选需要保留的中心区域</li><li>自动保存后，点击「下一张」处理下一张图片</li><li>重复步骤4-6直到所有图片处理完成</li></ol><p><strong>预期结果：</strong> 所有图片都会被裁剪成正方形，并保存在源文件夹下的「cropped_images」子文件夹中。</p><h4 id="场景二-制作宽屏桌面壁纸" tabindex="-1">场景二：制作宽屏桌面壁纸 <a class="header-anchor" href="#场景二-制作宽屏桌面壁纸" aria-label="Permalink to &quot;场景二：制作宽屏桌面壁纸&quot;">​</a></h4><p><strong>场景描述：</strong> 需要将多张风景照片裁剪成16:9比例用于桌面壁纸</p><p><strong>操作步骤：</strong></p><ol><li>启动程序</li><li>选择包含风景照片的文件夹</li><li>从下拉菜单中选择「16:9」比例</li><li>点击「裁剪图像」按钮</li><li>在图像上框选最适合的区域（程序会自动调整为精确的16:9比例）</li><li>保存后继续处理其他图片</li></ol><p><strong>预期结果：</strong> 所有照片将被裁剪成标准的16:9宽屏比例，适合作为桌面壁纸使用。</p><h4 id="场景三-产品图片自由裁剪" tabindex="-1">场景三：产品图片自由裁剪 <a class="header-anchor" href="#场景三-产品图片自由裁剪" aria-label="Permalink to &quot;场景三：产品图片自由裁剪&quot;">​</a></h4><p><strong>场景描述：</strong> 需要灵活裁剪不同形状的产品图片，没有固定比例要求</p><p><strong>操作步骤：</strong></p><ol><li>启动程序</li><li>选择产品图片文件夹</li><li>从下拉菜单中选择「自由裁剪」</li><li>点击「裁剪图像」按钮</li><li>精确框选产品区域，不限制形状</li><li>保存并继续处理其他产品图片</li></ol><p><strong>预期结果：</strong> 产品图片会按照您精确框选的区域进行裁剪，保留最重要的产品部分。</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统<br> 注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h3 id="📑-常见问题" tabindex="-1">📑 常见问题 <a class="header-anchor" href="#📑-常见问题" aria-label="Permalink to &quot;📑 常见问题&quot;">​</a></h3><p><strong>Q: 裁剪区域显示不正常？</strong></p><p>A: 尝试关闭程序重新启动，或检查图像文件是否损坏。</p><p><strong>Q: 选择文件夹后没有显示图像？</strong></p><p>A: 请确认文件夹中包含支持的图像格式（jpg、jpeg、png、bmp）。</p><p><strong>Q: 处理大图片时程序运行缓慢？</strong></p><p>A: 这是正常现象，大图片处理需要更多计算资源，请耐心等待。</p><p><strong>Q: 裁剪结果与框选区域不符？</strong></p><p>A: 当选择了固定比例时，程序会自动调整为精确比例，这是正常的功能设计。</p><h3 id="📑-演示视频" tabindex="-1">📑 演示视频 <a class="header-anchor" href="#📑-演示视频" aria-label="Permalink to &quot;📑 演示视频&quot;">​</a></h3><p><a href="https://www.bilibili.com/video/BV1e8WRz9E15/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1e8WRz9E15/</a></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/746.html" target="_blank" rel="noreferrer">https://www.softbangong.com/746.html</a></p>',77)])])}const _=r(i,[["render",n]]);export{c as __pageData,_ as default};
